 82→
 83→  const name = shopDisplayName(shop);
 84→
 85→  try {
 86→    await pm.sendEmail({
 87→      From: getFromEmail(),
 88→      To: to,
 89→      Subject: `New waitlist signup: ${zipCode}`,
 90→      HtmlBody: `
 91→        <div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px">
 92→          <h2 style="margin:0 0 16px">New waitlist signup</h2>
 93→          <p>A customer just joined the waitlist for ZIP code <strong>${zipCode}</strong>.</p>
 94→          <table style="margin:16px 0;border-collapse:collapse">
 95→            <tr><td style="padding:4px 12px 4px 0;color:#666">Email</td><td>${customerEmail}</td></tr>
 96→            <tr><td style="padding:4px 12px 4px 0;color:#666">ZIP Code</td><td>${zipCode}</td></tr>
 97→          </table>
 98→          <p style="color:#666;font-size:13px">You can manage the waitlist from your <strong>${name}</strong> admin dashboard.</p>
 99→        </div>
100→      `,
101→      TextBody: `New waitlist signup\n\nA customer (${customerEmail}) just joined the waitlist for ZIP code ${zipCode}.\n\nManage the waitlist from your ${name} admin dashboard.`,
102→      MessageStream: "outbound",
103→    });
104→    return true;
105→  } catch (error) {
106→    console.error("[email] Failed to send merchant waitlist alert:", error);
107→    return false;
108→  }
109→}
