   1→import { useState, useCallback, useMemo, useEffect } from "react";
   2→import type {
   3→  ActionFunctionArgs,
   4→  HeadersFunction,
   5→  LoaderFunctionArgs,
   6→} from "react-router";
   7→import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
   8→import { useAppBridge } from "@shopify/app-bridge-react";
   9→import { authenticate } from "../shopify.server";
  10→import { boundary } from "@shopify/shopify-app-react-router/server";
  11→import db from "../db.server";
  12→import { getShopSubscription } from "../billing.server";
  13→import { PLAN_LIMITS, UNLIMITED } from "../plans";
  14→import { sendZipAvailableNotification } from "../email.server";
  15→import {
  16→  Page,
  17→  Layout,
  18→  Card,
  19→  BlockStack,
  20→  InlineStack,
  21→  Text,
  22→  Button,
  23→  TextField,
  24→  Select,
  25→  Modal,
  26→  IndexTable,
  27→  EmptyState,
  28→  Divider,
  29→  Box,
  30→  Tooltip,
  31→  Icon,
  32→  Banner,
  33→  InlineGrid,
  34→  Checkbox,
  35→  type IndexTableProps,
  36→} from "@shopify/polaris";
  37→import {
  38→  SearchIcon,
  39→  DeleteIcon,
  40→  PlusIcon,
  41→  EmailIcon,
  42→} from "@shopify/polaris-icons";
  43→
  44→const PAGE_SIZE = 10;
  45→
  46→export const loader = async ({ request }: LoaderFunctionArgs) => {
  47→  const { session } = await authenticate.admin(request);
  48→  const shop = session.shop;
  49→
  50→  const [entries, subscription] = await Promise.all([
  51→    db.waitlistEntry.findMany({
  52→      where: { shop },
  53→      orderBy: { createdAt: "desc" },
  54→    }),
  55→    getShopSubscription(shop),
  56→  ]);
  57→
  58→  const stats = {
  59→    total: entries.length,
  60→    waiting: entries.filter((e) => e.status === "waiting").length,
  61→    accepted: entries.filter((e) => e.status === "accepted").length,
  62→    rejected: entries.filter((e) => e.status === "rejected").length,
  63→    notified: entries.filter((e) => e.status === "notified").length,
  64→    converted: entries.filter((e) => e.status === "converted").length,
  65→    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
  66→  };
  67→
  68→  return { entries, stats, subscription };
  69→};
  70→
  71→export const action = async ({ request }: ActionFunctionArgs) => {
  72→  const { session } = await authenticate.admin(request);
  73→  const shop = session.shop;
  74→  const formData = await request.formData();
  75→  const intent = formData.get("intent");
  76→
  77→  if (intent === "add") {
  78→    const email = String(formData.get("email") || "").trim().toLowerCase();
  79→    const zipCode = String(formData.get("zipCode") || "")
  80→      .trim()
  81→      .toUpperCase();
  82→    const note = String(formData.get("note") || "").trim() || null;
  83→
  84→    if (!email || !zipCode) return { error: "Email and zip code are required." };
  85→
  86→    const subscription = await getShopSubscription(shop);
  87→    const limits = PLAN_LIMITS[subscription.planTier];
  88→
  89→    if (limits.maxWaitlist === 0) {
  90→      return { error: "Your current plan does not include waitlist access. Upgrade to Starter or higher." };
  91→    }
  92→
  93→    if (limits.maxWaitlist < UNLIMITED) {
  94→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
  95→      if (currentCount >= limits.maxWaitlist) {
  96→        return { error: `You have reached the ${limits.maxWaitlist}-entry waitlist limit on your ${limits.label} plan. Upgrade to Pro for unlimited entries.` };
  97→      }
  98→    }
  99→
 100→    try {
 101→      await db.waitlistEntry.create({
 102→        data: { shop, email, zipCode, note },
 103→      });
 104→      return { success: true, action: "added" };
 105→    } catch {
 106→      return { error: "This email is already on the waitlist for this zip code." };
 107→    }
 108→  }
 109→
 110→  if (intent === "delete") {
 111→    const id = String(formData.get("id"));
 112→    try {
 113→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 114→      if (!existing) return { error: "Entry not found." };
 115→      await db.waitlistEntry.delete({ where: { id } });
 116→      return { success: true, action: "deleted" };
 117→    } catch {
 118→      return { error: "Failed to delete entry." };
 119→    }
 120→  }
 121→
 122→  if (intent === "update-status") {
 123→    const id = String(formData.get("id"));
 124→    const status = String(formData.get("status"));
 125→    try {
 126→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 127→      if (!existing) return { error: "Entry not found." };
 128→      await db.waitlistEntry.update({ where: { id }, data: { status } });
 129→      return { success: true, action: "updated" };
 130→    } catch {
 131→      return { error: "Failed to update entry status." };
 132→    }
 133→  }
 134→
 135→  if (intent === "notify-zip") {
 136→    const zipCode = String(formData.get("zipCode") || "").trim().toUpperCase();
 137→    if (!zipCode) return { error: "No ZIP code specified." };
 138→
 139→    const notifyZipSub = await getShopSubscription(shop);
 140→    if (PLAN_LIMITS[notifyZipSub.planTier].maxWaitlist < UNLIMITED) {
 141→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 142→    }
 143→
 144→    const notifyZipEntries = await db.waitlistEntry.findMany({
 145→      where: { shop, zipCode, status: "waiting" },
 146→      select: { id: true, email: true },
 147→    });
 148→
 149→    if (notifyZipEntries.length === 0) {
 150→      return { action: "notify-zip", zipCode, emails: [] as string[], count: 0 };
 151→    }
 152→
 153→    await db.waitlistEntry.updateMany({
 154→      where: { shop, zipCode, status: "waiting" },
 155→      data: { status: "notified" },
 156→    });
 157→
 158→    const emails = notifyZipEntries.map((e) => e.email);
 159→    const shopUrl = `https://${shop}`;
 160→    const emailResults = await Promise.allSettled(
 161→      emails.map((email) =>
 162→        sendZipAvailableNotification(email, zipCode, shop, shopUrl),
 163→      ),
 164→    );
 165→    const emailsSent = emailResults.filter(
 166→      (r) => r.status === "fulfilled" && r.value,
 167→    ).length;
 168→
 169→    return { action: "notify-zip", zipCode, emails, count: emails.length, emailsSent };
 170→  }
 171→
 172→  if (intent === "notify-selected-zips") {
 173→    const zipCodesRaw = String(formData.get("zipCodes") || "");
 174→    const zipCodes = zipCodesRaw.split(",").map(z => z.trim().toUpperCase()).filter(Boolean);
 175→    if (zipCodes.length === 0) return { error: "No ZIP codes selected." };
 176→
 177→    const notifyZipsSub = await getShopSubscription(shop);
 178→    if (PLAN_LIMITS[notifyZipsSub.planTier].maxWaitlist < UNLIMITED) {
 179→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 180→    }
 181→
 182→    const waitingEntries = await db.waitlistEntry.findMany({
 183→      where: { shop, status: "waiting", zipCode: { in: zipCodes } },
 184→      select: { id: true, email: true, zipCode: true },
 185→    });
 186→
 187→    if (waitingEntries.length === 0) {
 188→      return { action: "notify-selected-zips", emails: [] as string[], count: 0, zipBreakdown: [] as { zipCode: string; count: number }[] };
 189→    }
 190→
 191→    await db.waitlistEntry.updateMany({
 192→      where: { shop, status: "waiting", zipCode: { in: zipCodes } },
 193→      data: { status: "notified" },
 194→    });
 195→
 196→    const zipMap = new Map<string, number>();
 197→    for (const entry of waitingEntries) {
 198→      zipMap.set(entry.zipCode, (zipMap.get(entry.zipCode) ?? 0) + 1);
 199→    }
 200→    const zipBreakdown = Array.from(zipMap.entries()).map(([zipCode, count]) => ({ zipCode, count }));
 201→    const emails = waitingEntries.map(e => e.email);
 202→
 203→    const shopUrl = `https://${shop}`;
 204→    const emailResults = await Promise.allSettled(
 205→      waitingEntries.map((e) =>
 206→        sendZipAvailableNotification(e.email, e.zipCode, shop, shopUrl),
 207→      ),
 208→    );
 209→    const emailsSent = emailResults.filter(
 210→      (r) => r.status === "fulfilled" && r.value,
 211→    ).length;
 212→
 213→    return { action: "notify-selected-zips", emails, count: emails.length, zipBreakdown, emailsSent };
 214→  }
 215→
 216→  if (intent === "bulk-action") {
 217→    const idsRaw = String(formData.get("ids") || "");
 218→    const ids = idsRaw.split(",").filter(Boolean);
 219→    const bulkType = String(formData.get("bulkType") || "");
 220→
 221→    if (ids.length === 0) return { error: "No entries selected." };
 222→
 223→    const bulkSub = await getShopSubscription(shop);
 224→
 225→    if (bulkType === "notify") {
 226→      if (PLAN_LIMITS[bulkSub.planTier].maxWaitlist < UNLIMITED) {
 227→        return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 228→      }
 229→      const entriesToNotify = await db.waitlistEntry.findMany({
 230→        where: { id: { in: ids }, shop, status: "waiting" },
 231→        select: { id: true, email: true, zipCode: true },
 232→      });
 233→      if (entriesToNotify.length === 0) {
 234→        return { action: "bulk-action-notify", emails: [] as string[], count: 0, zipBreakdown: [] as { zipCode: string; count: number }[] };
 235→      }
 236→      await db.waitlistEntry.updateMany({
 237→        where: { id: { in: ids }, shop, status: "waiting" },
 238→        data: { status: "notified" },
 239→      });
 240→      const zipMap = new Map<string, number>();
 241→      for (const e of entriesToNotify) {
 242→        zipMap.set(e.zipCode, (zipMap.get(e.zipCode) ?? 0) + 1);
 243→      }
 244→      const zipBreakdown = Array.from(zipMap.entries()).map(([z, c]) => ({ zipCode: z, count: c }));
 245→
 246→      const shopUrl = `https://${shop}`;
 247→      const emailResults = await Promise.allSettled(
 248→        entriesToNotify.map((e) =>
 249→          sendZipAvailableNotification(e.email, e.zipCode, shop, shopUrl),
 250→        ),
 251→      );
 252→      const emailsSent = emailResults.filter(
 253→        (r) => r.status === "fulfilled" && r.value,
 254→      ).length;
 255→
 256→      return { action: "bulk-action-notify", emails: entriesToNotify.map(e => e.email), count: entriesToNotify.length, zipBreakdown, emailsSent };
 257→    }
 258→
 259→    if (bulkType === "accept") {
 260→      const entriesToAccept = await db.waitlistEntry.findMany({
 261→        where: { id: { in: ids }, shop },
 262→        select: { id: true, email: true, name: true, zipCode: true },
 263→      });
 264→      for (const entry of entriesToAccept) {
 265→        await db.zipCode.upsert({
 266→          where: { shop_zipCode: { shop, zipCode: entry.zipCode } },
 267→          create: { shop, zipCode: entry.zipCode, type: "allowed", isActive: true, label: `Requested by ${entry.name || entry.email}` },
 268→          update: { type: "allowed", isActive: true },
 269→        });
 270→      }
 271→      await db.waitlistEntry.updateMany({
 272→        where: { id: { in: ids }, shop },
 273→        data: { status: "accepted" },
 274→      });
 275→      return { success: true, action: "bulk-accepted", count: entriesToAccept.length };
 276→    }
 277→
 278→    if (bulkType === "reject") {
 279→      const result = await db.waitlistEntry.updateMany({
 280→        where: { id: { in: ids }, shop },
 281→        data: { status: "rejected" },
 282→      });
 283→      return { success: true, action: "bulk-rejected", count: result.count };
 284→    }
 285→
 286→    if (bulkType === "delete") {
 287→      const result = await db.waitlistEntry.deleteMany({
 288→        where: { id: { in: ids }, shop },
 289→      });
 290→      return { success: true, action: "bulk-deleted", count: result.count };
 291→    }
 292→
 293→    return { error: "Unknown bulk action type." };
 294→  }
 295→
 296→  if (intent === "delete-all-notified") {
 297→    const deleted = await db.waitlistEntry.deleteMany({
 298→      where: { shop, status: "notified" },
 299→    });
 300→    return { success: true, action: "deleted-notified", count: deleted.count };
 301→  }
 302→
 303→  if (intent === "accept") {
 304→    const id = String(formData.get("id"));
 305→    const entry = await db.waitlistEntry.findUnique({ where: { id } });
 306→    if (!entry || entry.shop !== shop) {
 307→      return { error: "Entry not found." };
 308→    }
 309→
 310→    await db.zipCode.upsert({
 311→      where: { shop_zipCode: { shop, zipCode: entry.zipCode } },
 312→      create: {
 313→        shop,
 314→        zipCode: entry.zipCode,
 315→        type: "allowed",
 316→        isActive: true,
 317→        label: `Requested by ${entry.name || entry.email}`,
 318→      },
 319→      update: {
 320→        type: "allowed",
 321→        isActive: true,
 322→      },
 323→    });
 324→
 325→    await db.waitlistEntry.update({
 326→      where: { id },
 327→      data: { status: "accepted" },
 328→    });
 329→
 330→    return { success: true, action: "accepted", zipCode: entry.zipCode };
 331→  }
 332→
 333→  if (intent === "reject") {
 334→    const id = String(formData.get("id"));
 335→    try {
 336→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 337→      if (!existing) return { error: "Entry not found." };
 338→      await db.waitlistEntry.update({
 339→        where: { id },
 340→        data: { status: "rejected" },
 341→      });
 342→      return { success: true, action: "rejected" };
 343→    } catch {
 344→      return { error: "Failed to reject entry." };
 345→    }
 346→  }
 347→
 348→  return null;
 349→};
 350→
 351→type WaitlistEntry = {
 352→  id: string;
 353→  name: string | null;
 354→  email: string;
 355→  zipCode: string;
 356→  note: string | null;
 357→  status: string;
 358→  createdAt: string | Date;
 359→};
 360→
 361→export default function WaitlistPage() {
 362→  const { entries, stats, subscription } = useLoaderData<typeof loader>();
 363→  const fetcher = useFetcher<typeof action>();
 364→  const shopify = useAppBridge();
 365→  const navigate = useNavigate();
 366→
 367→  const limits = PLAN_LIMITS[subscription.planTier];
 368→  const isFreePlan = limits.maxWaitlist === 0;
 369→  const isStarterPlan = limits.maxWaitlist < UNLIMITED && limits.maxWaitlist > 0;
 370→
 371→  const [searchQuery, setSearchQuery] = useState("");
 372→  const [statusFilter, setStatusFilter] = useState("all");
 373→  const [currentPage, setCurrentPage] = useState(1);
 374→  const [addModalOpen, setAddModalOpen] = useState(false);
 375→  const [notifyModalOpen, setNotifyModalOpen] = useState(false);
 376→  const [notifyResultModalOpen, setNotifyResultModalOpen] = useState(false);
 377→  const [notifyResult, setNotifyResult] = useState<{
 378→    zipCode: string;
 379→    emails: string[];
 380→    count: number;
 381→    emailsSent?: number;
 382→  } | null>(null);
 383→  const [copySuccess, setCopySuccess] = useState(false);
 384→
 385→  // ZIP checkbox selection
 386→  const [selectedZips, setSelectedZips] = useState<Set<string>>(new Set());
 387→
 388→  // IndexTable row selection
 389→  const [selectedEntryIds, setSelectedEntryIds] = useState<string[]>([]);
 390→
 391→  // Form state
 392→  const [newEmail, setNewEmail] = useState("");
 393→  const [newZipCode, setNewZipCode] = useState("");
 394→  const [newNote, setNewNote] = useState("");
 395→
 396→  const actionError =
 397→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
 398→
 399→  // Compute per-ZIP waiting counts for the "Notify Waitlist" section
 400→  const zipWaitingCounts = useMemo(() => {
 401→    const map = new Map<string, number>();
 402→    for (const e of entries as WaitlistEntry[]) {
 403→      if (e.status === "waiting") {
 404→        map.set(e.zipCode, (map.get(e.zipCode) ?? 0) + 1);
 405→      }
 406→    }
 407→    return Array.from(map.entries())
 408→      .map(([zipCode, count]) => ({ zipCode, count }))
 409→      .sort((a, b) => b.count - a.count);
 410→  }, [entries]);
 411→
 412→  // Handle notify results (zip, selected-zips, bulk-action-notify)
 413→  useEffect(() => {
 414→    if (
 415→      fetcher.data &&
 416→      "action" in fetcher.data &&
